                    # Provide a detailed, user friendly representation
                    def inspect
                        values = @properties.map{|k, v| "#{k}: #{v}"}.join(" ")
                        "<Twilio.Webhooks.V1.AuthProfileInstance #{values}>"
                    end
                end

            end
        end
    end
